import React, { memo } from 'react';

import {
  TRACK_SEPARATOR_STROKE_WIDTH,
  TRACK_SEPARATOR_COLOR,
} from '../constants.js';

type TrackSeparatorLineProps = {
  width: number;
  y: number;
  x: number;
};

/**
 * Draws a Track separator line.
 * @param width - width of the line
 * @param y - position of the line in the y axis
 * @param x - position of the line in the x axis
 */
export const TrackSeparatorLine = memo(
  ({ width, y = 0, x = 0 }: TrackSeparatorLineProps) => (
    <line
      y1={y}
      y2={y}
      x1={x}
      x2={x + width}
      strokeWidth={TRACK_SEPARATOR_STROKE_WIDTH}
      stroke={TRACK_SEPARATOR_COLOR}
    />
  ),
);

TrackSeparatorLine['displayName'] = 'TrackSeparatorLine';
